package io.fulfillx.notification;
import com.fasterxml.jackson.databind.ObjectMapper;import io.fulfillx.notification.application.NotificationProcessor;import io.fulfillx.notification.delivery.NotificationDeliveryAdapter;import io.fulfillx.notification.messaging.OrderEventEnvelope;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.testcontainers.junit.jupiter.Container;import org.testcontainers.junit.jupiter.Testcontainers;import org.testcontainers.postgresql.PostgreSQLContainer;import java.time.Instant;import java.util.UUID;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@SpringBootTest @AutoConfigureMockMvc @Testcontainers @ActiveProfiles("local") class NotificationIntegrationTest{
 @Container static final PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17-alpine");
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);r.add("notification.messaging.consumer-enabled",()->"false");}
 @Autowired MockMvc mvc;@Autowired NotificationProcessor processor;@Autowired ObjectMapper mapper;@Autowired JdbcTemplate jdbc;@MockitoBean NotificationDeliveryAdapter delivery;
 @BeforeEach void clear(){jdbc.update("DELETE FROM delivery_attempts");jdbc.update("DELETE FROM notifications");jdbc.update("DELETE FROM processed_messages");reset(delivery);}
 @Test void duplicateFinalEventCreatesAndDeliversOneNotification(){var e=event("OrderConfirmed",UUID.randomUUID());processor.process(e);processor.process(e);verify(delivery,times(1)).deliver(any());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM notifications",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM delivery_attempts WHERE status='DELIVERED'",Integer.class));assertEquals("order-"+e.aggregateId()+"@example.invalid",jdbc.queryForObject("SELECT recipient FROM notifications",String.class));}
 @Test void transientDeliveryFailureIsRecordedAndRetryCanSucceed(){var e=event("OrderCancelled",UUID.randomUUID());doThrow(new IllegalStateException("temporary SMTP failure")).doNothing().when(delivery).deliver(any());assertThrows(RuntimeException.class,()->processor.process(e));assertEquals("PENDING",jdbc.queryForObject("SELECT status FROM notifications",String.class));processor.process(e);assertEquals("DELIVERED",jdbc.queryForObject("SELECT status FROM notifications",String.class));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM delivery_attempts",Integer.class));}
 @Test void malformedOrUnsupportedVersionIsPermanentAndLeavesNoBusinessEffect(){var e=event("OrderConfirmed",UUID.randomUUID());var invalid=new OrderEventEnvelope(e.messageId(),e.messageType(),9,e.occurredAt(),e.correlationId(),e.causationId(),e.aggregateType(),e.aggregateId(),e.payload());assertThrows(IllegalArgumentException.class,()->processor.process(invalid));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM processed_messages",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM notifications",Integer.class));}
 @Test void concurrentDuplicateCannotStartASecondDeliveryWhileLeaseIsActive() throws Exception {var e=event("OrderConfirmed",UUID.randomUUID());var entered=new java.util.concurrent.CountDownLatch(1);var finish=new java.util.concurrent.CountDownLatch(1);doAnswer(invocation->{entered.countDown();if(!finish.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("test delivery timed out");return null;}).when(delivery).deliver(any());var pool=java.util.concurrent.Executors.newSingleThreadExecutor();try{var first=pool.submit(()->processor.process(e));assertTrue(entered.await(5,java.util.concurrent.TimeUnit.SECONDS));assertThrows(IllegalStateException.class,()->processor.process(e));finish.countDown();first.get(5,java.util.concurrent.TimeUnit.SECONDS);}finally{finish.countDown();pool.shutdownNow();}verify(delivery,times(1)).deliver(any());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM delivery_attempts",Integer.class));}
 @Test void localQueueBootstrapDefinesDlqsAndFinalEventFilter(){String init;try{init=java.nio.file.Files.readString(java.nio.file.Path.of("../../infrastructure/local/localstack/init/10-create-messaging.py"));}catch(Exception ex){throw new AssertionError("LocalStack messaging bootstrap must be present",ex);}assertTrue(init.contains("maxReceiveCount\": \"5\""));assertTrue(init.contains("NOTIFICATION_EVENTS_DLQ"));assertTrue(init.contains("OrderConfirmed"));assertTrue(init.contains("OrderRejected"));assertTrue(init.contains("OrderCancelled"));}
 @Test void actuatorRequiresAdminRoleButHealthIsPublic() throws Exception {mvc.perform(get("/actuator/health")).andExpect(status().isOk());mvc.perform(get("/actuator/prometheus")).andExpect(status().isUnauthorized());mvc.perform(get("/actuator/prometheus").with(jwt().authorities(()->"ROLE_OPERATIONS"))).andExpect(status().isForbidden());mvc.perform(get("/actuator/prometheus").with(jwt().authorities(()->"ROLE_ADMIN"))).andExpect(status().isOk());}
 private OrderEventEnvelope event(String type,UUID order){var p=mapper.createObjectNode().put("orderId",order.toString());if(type.equals("OrderConfirmed"))p.put("amount",25.50).put("currency","INR");else p.put("reasonCode","SAGA_RESULT");UUID id=UUID.randomUUID();return new OrderEventEnvelope(id,type,1,Instant.now(),order,id,"Order",order,p);}
}


